  tiger: [40,30,.10], snake: [20,70,.10], bear: [100,40,.20],
  crocodile: [130,30,.20], rhino: [160,20,.25], yak: [100,50,.20],
  falcon: [15,45,.05], bat: [10,50,.05], scorpion: [90,30,.10],
